-- High Pressure Needle Valve - Ultra High Pressure products (94, all priced) + filter values. Run AFTER the info file.
-- Source: Hiflux Mongo variant prices, facets parsed from each SKU (12 malformed NVNV* rows dropped).
DECLARE @SeriesName nvarchar(100) = N'High Pressure Needle Valve - Ultra High Pressure';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Pressure Rating'),(N'Stem'),(N'Tube Size'),(N'Body Type')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder
FROM (VALUES (N'Pressure Rating',0),(N'Stem',1),(N'Tube Size',2),(N'Body Type',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName
WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

